         max-width: 55ch;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.7;
       }

       .hero-actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.85rem;
         margin-top: 1.6rem;
       }

       .btn {
         display: inline-flex;
         align-items: center;
         justify-content: center;
         gap: 0.5rem;
         min-height: 48px;
         padding: 0.85rem 1.25rem;
         border-radius: 999px;
         border: 1px solid transparent;
         cursor: pointer;
         transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
       }

       .btn:hover,
       .btn:focus-visible {
         transform: translateY(-1px);
       }

       .btn-primary {
         color: white;
         background: linear-gradient(135deg, var(--brand-2), #334155);
         box-shadow: 0 16px 32px rgba(17, 24, 39, 0.2);
       }

       .btn-secondary {
         background: rgba(255, 255, 255, 0.82);
         border-color: var(--line);
         color: var(--text);
       }

       .hero-visual {
         position: absolute;
         inset: auto -4rem -5rem auto;
         width: min(44vw, 520px);
         aspect-ratio: 1 / 1;
         border-radius: 50%;
         background:
           radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.88), rgba(255, 255, 255, 0) 35%),
           linear-gradient(135deg, rgba(15, 118, 110, 0.32), rgba(217, 119, 6, 0.22));
         filter: blur(0.2px);
       }

       .hero-badge {
         position: absolute;
         right: 2rem;
         top: 2rem;
         padding: 0.9rem 1rem;
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.82);
         border: 1px solid var(--line);
         width: 220px;
       }

       .hero-badge strong,
       .card strong,
       .story strong {
         display: block;
       }

       .hero-badge span,
       .meta,
       .story p,
       .card p,
       .deal p {
         color: var(--muted);
       }

       .metrics {
         display: grid;
         grid-template-columns: repeat(3, 1fr);
         gap: 1rem;
         margin-top: 2.1rem;
       }

       .metric {
         padding: 1rem;
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.72);
